from pathlib import Path

path = Path("eureka-core/src/main/java/com/netflix/eureka/resources/ApplicationsResource.java")
text = path.read_text()

start_marker = "@GET"
end_marker = "    if (acceptHeader == null || !acceptHeader.contains(HEADER_JSON_VALUE)) {"

start_idx = text.find(start_marker)
if start_idx == -1:
    raise SystemExit("GET annotation for getContainers not found")
# Find the second occurrence of end_marker (first is for getContainers, second for delta method)
first_end = text.find(end_marker, start_idx)
second_end = text.find(end_marker, first_end + 1)
method_end_idx = second_end  # we stop right before delta's header-handling

prefix = text[:start_idx]
suffix = text[method_end_idx:]

replacement = """@GET
  public Response getContainers(
      @PathParam("version") String version,
      @HeaderParam(HEADER_ACCEPT) String acceptHeader,
      @HeaderParam(HEADER_ACCEPT_ENCODING) String acceptEncoding,
      @HeaderParam(EurekaAccept.HTTP_X_EUREKA_ACCEPT) String eurekaAccept,
      @Context UriInfo uriInfo,
      @Nullable @QueryParam("regions") String regionsStr) {

    boolean isRemoteRegionRequested = regionsStr != null && !regionsStr.isEmpty();
